def fill(path, d):
    txt = open(path, encoding="utf-8").read()
    out, missing = [], []
    for block in txt.split("\n\n"):
        m = re.search(r'^msgid ((?:".*"\n?)+)msgstr ((?:".*"\n?)+)', block, re.M)
        if m:
            mid = "".join(re.findall(r'"(.*)"', m.group(1)))
            if mid and mid in d:
                block = block[:m.start()] + 'msgid "%s"\nmsgstr "%s"' % (mid, d[mid]) + block[m.end():]
            elif mid and mid not in ("breast_cancer_risk", "derived_scenario"):
                missing.append(mid)
        out.append(block)
    open(path, "w", encoding="utf-8").write("\n\n".join(out))
    print(path, "untranslated:", missing)

fill("jamovi/i18n/es.po", ES)
fill("jamovi/i18n/ca.po", CA)
